        rules = [r for r in merge.RULES if r in g.rules]
        results.append((survivor, merged, rules, new, changes, src))
        lines.append(f"merge {ids.fmt(survivor)} <- {', '.join(ids.fmt(n) for n in merged)} ({', '.join(rules)})")
        for f, (before, after) in changes.items():
            lines.append(f"  {f}: {merge.dump(before)} -> {merge.dump(after)}")
    for x, y, rule in refused:
        lines.append(f"kept apart {ids.fmt(x)} {ids.fmt(y)} ({rule})")
