    lines.append(f"{len(results)} groups, {total} members merged, {len(refused)} pairs kept apart")
    if not a.apply:
        lines.append("dry run: nothing written")
    elif results:
        to_survivor = {}
        for survivor, merged, *_ in results:
            for n in merged:
                to_survivor[n] = survivor
        register = {n: r for n, r in reg.items() if n not in to_survivor}
        for survivor, _, _, new, _, _ in results:
            register[survivor] = new
